":["科教版","六年级","初中","kejiao16a-src:六年级:026_太阳能飞机","kejiao16a-src:初中:004_太阳能飞机"],"video":"https://assets.steamx.cc/kejiao16a/六年级/026_太阳能飞机/video_1.mp4"}]'::jsonb) AS e(id bigint,title text,tags text[],video text))
SELECT k.id,p.id,'candidate','unknown',k.revision,jsonb_build_object('basis','legacy_source_cohort_only','originalTags',e.tags,'originalVideoUrl',e.video,'reviewRequired',true),p.id
FROM experiment_kits k CROSS JOIN evidence_projects e JOIN projects p ON p.id=e.id AND p.title=e.title
WHERE k.id=ANY(ARRAY['09a6a552-92e2-5051-b31b-0adc64d38299','67ae051a-02c2-512f-b1f2-529cff911beb','d73f0432-6710-510f-ae72-f09d0611f203','ed7a2c19-9eeb-50a0-ae51-18cc3ff61d6c','e80e6b9d-9533-52ac-8e11-6880b05c4423','6e792062-9adf-578c-a44c-1feb6e788bd3','5b192982-c900-5f43-a17c-4d6122818d4b','63c9242e-1b6e-579a-980b-01765c560aa0','19a0f673-06ba-5bfc-be41-c21800258f92','166a8842-e66d-566b-963c-849bb654ef0b','e9f5b164-86cf-56cb-bced-45d650e569db','362a4ac3-6c37-52c4-beab-bb6745e8b428','dff7923f-63cf-5af7-99e6-5cbfd20801bd','522ae6c0-77ff-582b-847f-7830c455956b','01bf34f7-4d30-59be-a8a2-0e86a332b6e3','1cdae286-72fc-5c41-8f43-7922e3587fe4','2ec5bebf-be3b-5ac4-9e5e-5a507875da22','1ac69ea5-46b8-5e4c-bc92-a90b70595713']::uuid[])
AND k.catalog ? e.title
AND ((k.kind='general_materials' AND '趣味实验'=ANY(e.tags)) OR (k.kind='material_pack' AND '科教版'=ANY(e.tags) AND split_part(regexp_replace(k.name,'^2026',''),'16件套',1)=ANY(e.tags)))
ON CONFLICT DO NOTHING;
UPDATE projects p SET tags=ARRAY(SELECT t.tag FROM unnest(p.tags) WITH ORDINALITY AS t(tag,n) WHERE t.tag IS NULL OR btrim(t.tag) NOT IN ('趣味实验','科教版') ORDER BY t.n) WHERE EXISTS(SELECT 1 FROM unnest(p.tags) AS tag WHERE btrim(tag) IN ('趣味实验','科教版'));
